<script setup>
import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import * as THREE from 'three'
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls.js'
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js'
import { CAMPUS_BUILDING_TEMPLATES, createBuildingFootprintFromDesign, createPixelBuilding } from '../three/world/campus/campusAssetLibrary.js'
const API=(import.meta.env.VITE_API_BASE_URL||'http://localhost:3001/api/v1')+'/assets'
const USER=import.meta.env.VITE_DEV_USER_ID||'map-editor-local'
const name=ref('新建筑模板'),prompt=ref(''),extra=ref(''),modelType=ref('procedural'),sourceType=ref('ai_generated')
const image=ref(null),glb=ref(null),imageUrl=ref(''),glbUrl=ref(''),approved=ref(false),approvalToken=ref(''),design=ref(null),designToken=ref(''),model=ref('')
const busy=ref(false),error=ref(''),message=ref(''),templates=ref([]),v25=ref(null),v3d=ref(null),previews=[],draftId=ref(''),uploadedRoles=ref([])
const readyCount=computed(()=>templates.value.filter(x=>x.status==='ready').length)
async function api(path,options={}){const r=await fetch(API+path,{...options,headers:{'X-Dev-User-Id':USER,...(options.headers||{})}});const d=await r.json().catch(()=>({}));if(!r.ok){const raw=d.message??d.error?.message;const detail=Array.isArray(raw)?raw.join('；'):raw;console.error('[BuildingTemplateWorkshop]',r.status,path,d);throw new Error((detail||'请求失败')+'（HTTP '+r.status+'）')}return d}
const toDataUrl=file=>new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(new Error('读取文件失败'));r.readAsDataURL(file)})
function invalidateApproval(){approved.value=false;approvalToken.value='';design.value=null;designToken.value=''}
function onImage(e){if(imageUrl.value)URL.revokeObjectURL(imageUrl.value);imageUrl.value='';image.value=null;invalidateApproval();const f=e.target.files?.[0];if(!f)return;if(!['image/png','image/jpeg','image/webp'].includes(f.type)||f.size>10*1024*1024){error.value='图片仅支持 PNG/JPG/WebP，且不超过10MB';return}image.value=f;imageUrl.value=URL.createObjectURL(f);sourceType.value='external';error.value='';message.value='参考图已载入，请先检查预览。'}
function onGlb(e){if(glbUrl.value)URL.revokeObjectURL(glbUrl.value);glbUrl.value='';glb.value=null;const f=e.target.files?.[0];if(!f)return;if(!f.name.toLowerCase().endsWith('.glb')||f.size>30*1024*1024){error.value='GLB 文件不能超过30MB';return}glb.value=f;glbUrl.value=URL.createObjectURL(f);error.value='';nextTick(renderPreviews)}
function makePrompt(){prompt.value=['Create one original stylized low-poly university campus building.','Template name: '+name.value+'.','Show front facade, side facade, roof, floors, windows and entrance in one elevated three-quarter view.','Warm natural palette, clear silhouette, game-ready detail.','One isolated building only; no campus panorama, terrain, roads, trees, people, text, watermark or UI.',extra.value].filter(Boolean).join('\n\n')}
async function generate(){if(busy.value)return;if(!prompt.value.trim())makePrompt();busy.value=true;error.value='';message.value='正在生成建筑参考图……';try{const d=await api('/ai-image/generate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({prompt:prompt.value})});const blob=await(await fetch(d.dataUrl)).blob();if(!blob.size||blob.size>10*1024*1024)throw new Error('生成图片为空或超过10MB');if(imageUrl.value)URL.revokeObjectURL(imageUrl.value);image.value=new File([blob],'ai-building-reference.png',{type:d.mimeType||blob.type});imageUrl.value=URL.createObjectURL(image.value);sourceType.value='ai_generated';model.value=d.model||'';invalidateApproval();message.value='图片已生成。确认预览前不会调用结构识别。'}catch(e){error.value=e.message}finally{busy.value=false}}
async function confirmImage(){if(!image.value||busy.value)return;busy.value=true;try{const d=await api('/ai-image/approve-reference',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({imageDataUrl:await toDataUrl(image.value)})});if(!d.approvalToken)throw new Error('服务端未返回确认凭证');approvalToken.value=d.approvalToken;approved.value=true;message.value='图片确认完成，可以进行结构识别。'}catch(e){error.value=e.message}finally{busy.value=false}}
async function analyze(){if(!approved.value||!approvalToken.value||!image.value||busy.value)return;busy.value=true;error.value='';try{const d=await api('/ai-image/analyze-building',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({imageDataUrl:await toDataUrl(image.value),approvalToken:approvalToken.value,prompt:prompt.value || extra.value})});if(!d.design||d.design.schemaVersion!==1)throw new Error('未返回有效建筑参数');design.value=d.design;designToken.value=d.designToken||'';if(!designToken.value)throw new Error('服务端未返回结构参数签名');message.value='参数提取完成，已生成程序化 Mesh 预览。';await nextTick(renderPreviews)}catch(e){design.value=null;designToken.value='';approved.value=false;approvalToken.value='';error.value=e.message+'。请检查页面错误详情；如提示确认凭证无效，请重新确认当前图片后再识别。'}finally{busy.value=false}}
function dispose(){previews.splice(0).forEach(p=>{cancelAnimationFrame(p.frame);p.observer.disconnect();p.controls.dispose();p.renderer.dispose();p.scene.traverse(o=>{o.geometry?.dispose();if(o.material)(Array.isArray(o.material)?o.material:[o.material]).forEach(m=>m.dispose())})})}
function preview(container,mode){if(!container)return null;const w=Math.max(240,container.clientWidth||320),h=Math.max(180,container.clientHeight||230),renderer=new THREE.WebGLRenderer({antialias:true,alpha:true});renderer.setPixelRatio(Math.min(devicePixelRatio||1,1.5));renderer.setSize(w,h);container.replaceChildren(renderer.domElement);const scene=new THREE.Scene();scene.background=new THREE.Color('#edf2eb');scene.add(new THREE.HemisphereLight(0xffffff,0x9aa58e,2));const light=new THREE.DirectionalLight(0xffffff,2);light.position.set(10,18,12);scene.add(light);const floor=new THREE.Mesh(new THREE.PlaneGeometry(30,24),new THREE.MeshStandardMaterial({color:'#cbd5c3'}));floor.rotation.x=-Math.PI/2;floor.position.y=-.08;scene.add(floor);
 const palette={wallCream:'#e7d8b8',wallPeach:'#d9a58b',wallMint:'#b7c9ad',wall:'#d9d0bc',roof:'#8e5945',roofRed:'#8e5945',roofGray:'#70777b',roofGreen:'#647b59',roofBlue:'#536f91',roofDark:'#684638',window:'#86aeb0',windowTrim:'#f1e5ca',door:'#795640',stoneLight:'#d6c7a8'},materials=Object.fromEntries(Object.entries(palette).map(([k,v])=>[k,new THREE.MeshStandardMaterial({color:v,roughness:.85})]));
 const aspect=w/h,camera=mode==='2.5d'?new THREE.OrthographicCamera(-10*aspect,10*aspect,10,-10,.1,100):new THREE.PerspectiveCamera(38,aspect,.1,100);camera.position.set(12,mode==='2.5d'?17:10,15);camera.lookAt(0,2.2,0);
 if(modelType.value==='glb'&&glbUrl.value){new GLTFLoader().load(glbUrl.value,g=>{const obj=g.scene,b=new THREE.Box3().setFromObject(obj),s=b.getSize(new THREE.Vector3());obj.scale.setScalar(8/Math.max(s.x,s.y,s.z,.001));const n=new THREE.Box3().setFromObject(obj),c=n.getCenter(new THREE.Vector3());obj.position.set(-c.x,-n.min.y,-c.z);scene.add(obj);renderer.render(scene,camera)},undefined,e=>error.value='GLB预览失败：'+e.message)}else{const preset=CAMPUS_BUILDING_TEMPLATES[design.value?.template||'教学楼']||CAMPUS_BUILDING_TEMPLATES['教学楼'],d=design.value||preset;scene.add(createPixelBuilding(THREE,{footprint:createBuildingFootprintFromDesign(THREE,8,6,d),width:8,depth:6,height:d.height||preset.height,template:d.template||'教学楼',facadeStyle:d.facadeStyle||'modern',hasBalconies:d.hasBalconies===true,balconyFloors:d.balconyFloors||[],columnCount:d.columnCount||0,roofColor:d.roofColor||'roofRed',facadeSections:d.facadeSections||1,hasArcade:d.hasArcade===true,podiumFloors:d.podiumFloors||0,entranceEdgeIndex:({front:0,right:1,rear:2,left:3}[d.entrancePosition]??0),materials,floors:d.floors??preset.floors,roofStyle:d.roofStyle||preset.roofStyle,roofRise:d.roofRise??preset.roofRise,windowDensity:d.windowDensity??preset.windowDensity,windowWidth:d.windowWidth??preset.windowWidth,windowHeight:d.windowHeight??preset.windowHeight,doorWidth:d.doorWidth??preset.doorWidth,wallMaterial:materials[d.wallPalette]||materials[preset.wall]||materials.wallCream}))}
 const controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=true;controls.enablePan=false;controls.target.set(0,2.2,0);controls.update();const render=()=>renderer.render(scene,camera);let frame;const animate=()=>{controls.update();render();frame=requestAnimationFrame(animate)};animate();const observer=new ResizeObserver(()=>{const nw=Math.max(1,container.clientWidth),nh=Math.max(1,container.clientHeight);renderer.setSize(nw,nh);if(camera.isPerspectiveCamera)camera.aspect=nw/nh;else{camera.left=-10*nw/nh;camera.right=10*nw/nh}camera.top=10;camera.bottom=-10;camera.updateProjectionMatrix();render()});observer.observe(container);return{renderer,scene,controls,observer,frame}}
function renderPreviews(){dispose();const a=preview(v25.value,'2.5d'),b=preview(v3d.value,'3d');if(a)previews.push(a);if(b)previews.push(b)}
watch([design,glbUrl,modelType],()=>nextTick(renderPreviews),{deep:true})
async function upload(id,role,file){const f=new FormData();f.append('file',file,file.name);return api('/building-templates/'+id+'/files/'+role,{method:'POST',body:f})}
async function publish(){if(busy.value)return;if(modelType.value==='procedural'&&(!design.value||!approved.value||!designToken.value)){error.value='程序化模板必须先确认图片并完成结构识别';return}if(modelType.value==='glb'&&!glb.value){error.value='请上传 GLB 模型';return}busy.value=true;error.value='';try{if(!draftId.value){const item=await api('/building-templates',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:name.value,category:'building',sourceType:sourceType.value,modelType:modelType.value,buildingDesign:design.value,designToken:designToken.value,prompt:prompt.value,generationModel:model.value})});draftId.value=item.templateId}if(image.value&&!uploadedRoles.value.includes('reference')){await upload(draftId.value,'reference',image.value);uploadedRoles.value.push('reference')}if(glb.value&&!uploadedRoles.value.includes('model')){await upload(draftId.value,'model',glb.value);uploadedRoles.value.push('model')}await api('/building-templates/'+draftId.value+'/approve',{method:'PATCH'});message.value='独立模板已发布：'+name.value;draftId.value='';uploadedRoles.value=[];await load()}catch(e){error.value=e.message+'；草稿和已上传文件状态已保留，可重试发布。'}finally{busy.value=false}}
async function load(){try{const d=await api('/building-templates');templates.value=d.templates||[]}catch(e){error.value=e.message}}
function back(){location.assign('/')}
onMounted(async()=>{await load();await nextTick();renderPreviews()})
onBeforeUnmount(()=>{if(imageUrl.value)URL.revokeObjectURL(imageUrl.value);if(glbUrl.value)URL.revokeObjectURL(glbUrl.value);dispose()})
</script>
<template><main class="workshop"><header><div><small>ASSET PIPELINE</small><h1>建筑模板工坊</h1><p>独立创建，不绑定校园对象</p></div><button @click="back">返回校园地图</button></header><div class="grid"><section class="panel"><h2>01 / 模板定义</h2><label>模板名称<input v-model="name" placeholder="现代教学楼 A 型"></label><label>提示词<textarea v-model="prompt" rows="5" placeholder="建筑外观、楼层、屋顶、立面、材质"></textarea></label><label>补充要求<textarea v-model="extra" rows="2"></textarea></label><div class="actions"><button class="secondary" @click="makePrompt">生成提示词</button><button :disabled="busy" @click="generate">AI 生成图片</button></div><label>参考图片<input type="file" accept="image/png,image/jpeg,image/webp" @change="onImage"></label><div v-if="imageUrl" class="image"><img :src="imageUrl" alt="建筑参考图"></div><div class="actions"><button class="secondary" :disabled="!image||approved||busy" @click="confirmImage">{{approved?'图片已确认':'确认图片预览'}}</button><button :disabled="!approved||busy" @click="analyze">确认后识别 3D 参数</button></div><p v-if="approved" class="hint">图片已确认；替换图片后必须重新确认。</p><label>最终模型来源<select v-model="modelType"><option value="procedural">识图参数 → 程序化 3D</option><option value="glb">直接使用 GLB</option></select></label><label>GLB 文件<input type="file" accept=".glb,model/gltf-binary" @change="onGlb"></label><p v-if="glb" class="hint">{{glb.name}}</p><div v-if="design" class="design">{{design.template}} · {{design.massing}} · {{design.floors}}层 · {{design.facadeStyle}}立面 · {{design.roofStyle}}屋顶 · 阳台{{design.hasBalconies?'有':'无'}} · 柱廊{{design.columnCount}}柱 · 置信度 {{Math.round(design.confidence*100)}}%<small>高度为场景视觉估算，不是测绘值。</small></div><button class="publish" :disabled="busy || (modelType==='procedural' && (!design || !designToken)) || (modelType==='glb' && !glb)" @click="publish">{{busy?'处理中…':'保存并发布独立模板'}}</button><p class="error">{{error}}</p><p class="message">{{message}}</p></section><section class="panel"><h2>02 / 实体模型预览</h2><div class="previews"><div><b>2.5D · 正交斜俯视</b><div ref="v25" class="viewport"></div></div><div><b>3D · 透视观察</b><div ref="v3d" class="viewport"></div></div></div><p class="hint">同一份真实 Mesh 或 GLB，仅相机投影不同。拖动旋转检查背面，滚轮缩放。</p><h2>03 / 模板库 · {{readyCount}} 个已发布</h2><div v-if="!templates.length" class="empty">暂无已发布模板</div><div v-for="t in templates" :key="t.templateId" class="item"><b>{{t.name}}</b><span>{{t.modelType}} · {{t.status}}</span><small>{{t.templateId}}</small></div></section></div><footer>模板只定义几何与外观，不包含校园位置、footprint、碰撞或 walkable。AI 图片只用于识别和追溯，不作为地图贴图；地图编辑器负责套用模板。</footer></main></template>
<style scoped>
.workshop{height:100%;overflow:auto;padding:26px clamp(14px,3vw,42px);background:#edf1eb;color:#26372e;font-family:Arial,'Noto Sans SC',sans-serif}header{max-width:1400px;margin:0 auto 20px;display:flex;justify-content:space-between;align-items:center}header small{letter-spacing:2px;color:#748575;font-size:10px}h1{margin:8px 0 4px}header p,.hint{color:#829087;font-size:11px}.grid{max-width:1400px;margin:auto;display:grid;grid-template-columns:.9fr 1.1fr;gap:18px}.panel{min-width:0;padding:20px;background:white;border:1px solid #d9e1d7;border-radius:10px}.panel h2{font-size:12px;margin:0 0 14px}.panel label{display:flex;flex-direction:column;gap:7px;margin:12px 0;font-size:11px}.panel input,.panel textarea,.panel select{padding:9px;border:1px solid #dce4da;border-radius:6px;font:inherit}.actions{display:flex;gap:8px;flex-wrap:wrap;margin:12px 0}button{padding:9px 13px;border:1px solid #315b43;border-radius:6px;background:#315b43;color:white;cursor:pointer;font-size:11px}button.secondary{background:white;color:#315b43}button:disabled{opacity:.45}.image{display:grid;place-items:center;max-height:250px;overflow:hidden;background:#f2f5f0}.image img{max-width:100%;max-height:245px;object-fit:contain}.publish{width:100%;margin-top:12px}.design{padding:12px;background:#f4f8f2;font-size:11px}.design small{display:block;color:#829087;margin-top:5px}.error{color:#b44e43;font-size:11px}.message{color:#426a4b;font-size:11px}.previews{display:grid;grid-template-columns:1fr 1fr;gap:12px}.previews>div{min-width:0;font-size:11px}.viewport{height:245px;margin-top:8px;border-radius:7px;overflow:hidden}.viewport canvas{width:100%;height:100%;display:block}.item{display:flex;flex-direction:column;gap:4px;padding:11px 0;border-bottom:1px solid #eee;font-size:11px}.item span,.item small{color:#829087;font-size:10px}.empty{padding:20px;text-align:center;color:#829087;font-size:12px}footer{max-width:1400px;margin:18px auto 0;padding:14px 0;border-top:1px solid #d8e1d6;color:#7a887d;font-size:10px;line-height:1.7}@media(max-width:900px){.grid{grid-template-columns:1fr}}@media(max-width:600px){.workshop{padding:14px}.panel{padding:14px}.previews{grid-template-columns:1fr}}
</style>